            r'(?://(?P<authority>[^/?#]*))?'
            r'(?P<path>[^?#]*)'
            r'(?:\?(?P<query>[^#]*))?'
            r'(?:#(?P<fragment>.*))?'
        )
        match = pattern.match(uri)
        if not match:
            # Should not happen with the pattern above, but handle gracefully
            return {
                'scheme': '',
                'authority': None,
                'path': uri,
                'query': None,
                'fragment': None
            }
        return {
            'scheme': match.group('scheme') or '',
            'authority': match.group('authority') if match.group('authority') is not None else None,
            'path': match.group('path') or '',
            'query': match.group('query'),
            'fragment': match.group('fragment')
        }

