                        path = path[segment_end:]
                    output.append(segment)
                else:
                    segment_end = path.find('/')
                    if segment_end == -1:
                        segment = path
                        path = ''
                    else:
                        segment = path[:segment_end]
                        path = path[segment_end:]
                    output.append(segment)
